username = #{username}, password = #{password}, name = #{name}, phone = #{phone}, id_card = #{idCard}, id_card_front = #{idCardFront}, id_card_back = #{idCardBack}, work_status = #{workStatus}, rating = #{rating}, order_count = #{orderCount}, today_order_count = #{todayOrderCount}, location_lat = #{locationLat}, location_lng = #{locationLng}, location_update_time = #{locationUpdateTime}, max_daily_orders = #{maxDailyOrders}, service_area = #{serviceArea}, status = #{status}, audit_status = #{auditStatus}, reject_reason = #{rejectReason},
